import React, { useState } from 'react'
import { useCart, useDispatchCart } from './ContextReducer';

export default function Card(props) {
    let dispatch = useDispatchCart();
    let option = props.options ?? {};
    let priceOptions = Object.keys(option);
    let data = useCart();
    const foodItem = props.foodItem;
    const [qty, setQty] = usestate(1);
    const [size, setSize] = useState("");
    const handleAddToCart = async ()=>{
     await dispatch({type:"ADD", id:foodItem._id, name:props.foodItem.name, price: props.finalPrice, qty:qty, size:size })
     console.log(data);
    }

    return (
        <div>
            <div>
                <div className="card mt-3 ml-3" style={{ "width": "18rem", "maxHeight": "400px" }}>
                    <img src= {foodItem.img} className="card-img-top" alt="..." style={{height:"170px", objectFit:"fill"}} />
                    <div className="card-body">
                        <h5 className="card-title">{props.foodItem.name}</h5>

                        <div className='container w-100'>
                            <select className='m-2 h-100  bg-success rounded' onChange={(e) => setQty(e.target.value)}>
                                {Array.from(Array(6), (e, i) => {
                                    return (
                                        <option key={i + 1} value={i + 1}> {i + 1} </option>
                                    )
                                })}
                            </select>
                            <select className='-2 h-100  bg-success rounded' onChange={(e) => setSize(e.target.value)} >
                                {priceOptions.map((data) => (
                                    <option key={data} value={data}>{data}</option>
                                ))}
                            </select>
                            <div className='d-inline h-30 fs-6 m-3'>Total Price</div>
                        </div>
                        <hr />
                        <button className={'btn btn-success justify ms-2'} onClick={handleAddToCart}>Add To Cart</button>
                    </div>
                </div>
            </div>

            <br></br>
        </div>
    )
}
